<?php require 'includes/functions.php'; if(is_logged_in())go('index.php');if($_SERVER['REQUEST_METHOD']==='POST'){ $f=['full_name','username','email','mobile','password','confirm','address'];foreach($f as $x)if(empty(trim($_POST[$x]??''))){flash('danger','All fields are required.');go('register.php');}if(!filter_var($_POST['email'],FILTER_VALIDATE_EMAIL)||!preg_match('/^[6-9][0-9]{9}$/',$_POST['mobile'])){flash('danger','Enter a valid email and 10-digit mobile number.');go('register.php');}if(strlen($_POST['password'])<8||$_POST['password']!==$_POST['confirm']){flash('danger','Passwords must match and contain at least 8 characters.');go('register.php');}try{db()->prepare('INSERT INTO users(full_name,username,email,mobile,password,address) VALUES(?,?,?,?,?,?)')->execute([trim($_POST['full_name']),trim($_POST['username']),trim($_POST['email']),trim($_POST['mobile']),password_hash($_POST['password'],PASSWORD_DEFAULT),trim($_POST['address'])]);flash('success','Registration successful. Your account is blocked until an admin approves it.');go('user-login.php');}catch(PDOException $e){flash('danger','Username, email, or mobile already exists.');go('register.php');}}$pageTitle='Register';require 'includes/header.php';require 'includes/navbar.php'; ?>
<main class="container my-5" style="max-width:680px"><h1 class="section-title">Create your OVERSO account</h1><p>New accounts need admin approval before login.</p><form method="post" class="card card-body shadow-sm"><div class="row g-3"><div class="col-md-6"><label>Full name</label><input class="form-control" name="full_name" required></div><div class="col-md-6"><label>Username</label><input class="form-control" name="username" required></div><div class="col-md-6"><label>Email</label><input class="form-control" name="email" type="email" required></div><div class="col-md-6"><label>Mobile</label><input class="form-control" name="mobile" maxlength="10" required></div><div class="col-md-6"><label>Password</label><input class="form-control" name="password" type="password" minlength="8" required></div><div class="col-md-6"><label>Confirm password</label><input class="form-control" name="confirm" type="password" minlength="8" required></div><div class="col-12"><label>Address</label><textarea class="form-control" name="address" required></textarea></div><div><button class="btn btn-dark">Register</button> <a href="<?=base('user-login.php')?>">Already registered?</a></div></div></form></main><?php require 'includes/footer.php'; ?>
